CREATE TABLE IF NOT EXISTS rumo10_migrations (version VARCHAR(40) PRIMARY KEY, applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rumo10_contas (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, senha_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rumo10_login_limits (fingerprint CHAR(64) PRIMARY KEY, attempts INT NOT NULL DEFAULT 0, window_start BIGINT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rumo10_clubes (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(80) UNIQUE NOT NULL, nome VARCHAR(120) NOT NULL, municipio VARCHAR(80) NOT NULL, uf CHAR(2) NOT NULL DEFAULT 'SP', origem VARCHAR(10) NOT NULL, cor_primaria_nome VARCHAR(30) NOT NULL, cor_primaria_hex CHAR(7) NOT NULL, cor_secundaria_nome VARCHAR(30) NOT NULL, cor_secundaria_hex CHAR(7) NOT NULL, cor_terciaria_nome VARCHAR(30) NULL, cor_terciaria_hex CHAR(7) NULL, fonte_cores_url TEXT NULL, verificacao VARCHAR(40) NOT NULL DEFAULT 'briefing_provisorio', cores_verificadas_em DATE NULL, tier_ficticio INT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rumo10_carreiras (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, conta_id BIGINT UNSIGNED NOT NULL UNIQUE, nome VARCHAR(60) NOT NULL, cidade VARCHAR(80) NOT NULL, uf CHAR(2) NOT NULL, posicao VARCHAR(20) NOT NULL, idade INT NOT NULL, temporada INT NOT NULL DEFAULT 1, rodada INT NOT NULL DEFAULT 1, etapa VARCHAR(30) NOT NULL, clube VARCHAR(120) NOT NULL, tier INT NOT NULL DEFAULT 1, handicap VARCHAR(80) NULL, versao INT NOT NULL DEFAULT 0, feedback_json JSON NULL, FOREIGN KEY(conta_id) REFERENCES rumo10_contas(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rumo10_atributos (carreira_id BIGINT UNSIGNED NOT NULL, habilidade VARCHAR(30) NOT NULL, valor INT NOT NULL, xp INT NOT NULL DEFAULT 0, PRIMARY KEY(carreira_id,habilidade), CHECK(valor BETWEEN 0 AND 100), CHECK(xp>=0), FOREIGN KEY(carreira_id) REFERENCES rumo10_carreiras(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rumo10_estados (carreira_id BIGINT UNSIGNED NOT NULL, indicador VARCHAR(40) NOT NULL, valor INT NOT NULL, PRIMARY KEY(carreira_id,indicador), CHECK(valor BETWEEN 0 AND 100), FOREIGN KEY(carreira_id) REFERENCES rumo10_carreiras(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rumo10_temporadas (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, carreira_id BIGINT UNSIGNED NOT NULL, numero INT NOT NULL, clube VARCHAR(120) NOT NULL, finalizada TINYINT NOT NULL DEFAULT 0, resumo_json JSON NULL, UNIQUE(carreira_id,numero), FOREIGN KEY(carreira_id) REFERENCES rumo10_carreiras(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rumo10_times (temporada_id BIGINT UNSIGNED NOT NULL, nome VARCHAR(120) NOT NULL, PRIMARY KEY(temporada_id,nome), FOREIGN KEY(temporada_id) REFERENCES rumo10_temporadas(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rumo10_partidas (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, temporada_id BIGINT UNSIGNED NOT NULL, rodada INT NOT NULL, mandante VARCHAR(120) NOT NULL, visitante VARCHAR(120) NOT NULL, gols_mandante INT NOT NULL DEFAULT 0, gols_visitante INT NOT NULL DEFAULT 0, minuto INT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'agendada', escalacao VARCHAR(30) NOT NULL DEFAULT '', entrada INT NOT NULL DEFAULT 0, saida INT NOT NULL DEFAULT 0, UNIQUE(temporada_id,rodada,mandante), INDEX(temporada_id,rodada,status), CHECK(mandante<>visitante), FOREIGN KEY(temporada_id) REFERENCES rumo10_temporadas(id), FOREIGN KEY(temporada_id,mandante) REFERENCES rumo10_times(temporada_id,nome), FOREIGN KEY(temporada_id,visitante) REFERENCES rumo10_times(temporada_id,nome)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rumo10_estatisticas (partida_id BIGINT UNSIGNED PRIMARY KEY, minutos INT NOT NULL, gols INT NOT NULL, assistencias INT NOT NULL, passes INT NOT NULL, passes_certos INT NOT NULL, finalizacoes INT NOT NULL, desarmes INT NOT NULL, faltas INT NOT NULL, cartoes INT NOT NULL, nota DECIMAL(4,1) NOT NULL, CHECK(passes_certos<=passes), CHECK(minutos BETWEEN 0 AND 90), FOREIGN KEY(partida_id) REFERENCES rumo10_partidas(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rumo10_eventos_partida (partida_id BIGINT UNSIGNED NOT NULL, sequencia INT NOT NULL, minuto INT NOT NULL, texto TEXT NOT NULL, PRIMARY KEY(partida_id,sequencia), FOREIGN KEY(partida_id) REFERENCES rumo10_partidas(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rumo10_situacoes (id INT PRIMARY KEY, momento VARCHAR(30) NOT NULL, texto TEXT NOT NULL, versao VARCHAR(20) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rumo10_opcoes (situacao_id INT NOT NULL, opcao INT NOT NULL, texto TEXT NOT NULL, efeitos_json JSON NOT NULL, PRIMARY KEY(situacao_id,opcao), FOREIGN KEY(situacao_id) REFERENCES rumo10_situacoes(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rumo10_decisoes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, carreira_id BIGINT UNSIGNED NOT NULL, chave CHAR(64) NOT NULL, comando VARCHAR(30) NOT NULL, request_hash CHAR(64) NOT NULL, versao_anterior INT NOT NULL, chance DECIMAL(5,2) NULL, sorteio INT NULL, classe VARCHAR(30) NULL, regras VARCHAR(20) NOT NULL, resultado_json JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(carreira_id,chave), FOREIGN KEY(carreira_id) REFERENCES rumo10_carreiras(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rumo10_ofertas (temporada_id BIGINT UNSIGNED NOT NULL, clube VARCHAR(120) NOT NULL, tier INT NOT NULL, peso INT NOT NULL, selecionada TINYINT NOT NULL DEFAULT 0, PRIMARY KEY(temporada_id,clube), FOREIGN KEY(temporada_id) REFERENCES rumo10_temporadas(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rumo10_transferencias (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, carreira_id BIGINT UNSIGNED NOT NULL, temporada INT NOT NULL, origem VARCHAR(120) NOT NULL, destino VARCHAR(120) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(carreira_id,temporada), FOREIGN KEY(carreira_id) REFERENCES rumo10_carreiras(id)) ENGINE=InnoDB;
